[package]
name = "paigasus-redis"
version = "0.0.0"
edition.workspace = true
license.workspace = true
rust-version.workspace = true
authors.workspace = true
publish = false

[dependencies]
# SMA-677 D19: `script` gives `redis::Script` (EVALSHA with a NOSCRIPT -> SCRIPT LOAD retry) to the
# gateway's limit store. Added here, not in the workspace table, so the workspace comment that
# trims `script` stays true for every other consumer. Cargo unions features, so IAM builds it too;
# that changes no IAM behavior.
redis = { workspace = true, features = ["script"] }
metrics = { workspace = true }
# Only the `test_support` blackhole listener needs tokio, so it comes in with the feature.
tokio = { workspace = true, features = ["rt", "net", "sync", "io-util"], optional = true }

[dev-dependencies]
lib.rs
// SPDX-License-Identifier: Apache-2.0

//! The single place a Paigasus service constructs a Redis [`ConnectionManager`] (SMA-473).
//!
//! Moved out of `paigasus-iam`'s `adapters::redis_conn` by SMA-726 (D15), so that IAM and the
//! gateway share one tuned connection and one circuit breaker. The caller names the breaker's
//! metrics with [`BreakerMetrics`]; this crate does not depend on `paigasus-observability`.
//! The `test-support` feature adds the test-only constructors and the `test_support` blackhole
//! listener. Turn it on from `[dev-dependencies]` only.
//!
//! **Why this module exists.** `ConnectionManager::new` applies a stock
//! `ConnectionManagerConfig::default()`, whose reconnect budget is 6 retries on a
//! `100+200+400+800+1600+3200 ms` schedule. `backon` adds jitter (`delay × [1,2]`), so a
//! dead backend costs ~6.3–12.6 s per cycle — and a `ConnectionManager` burns a full cycle
//! per failed command, because the failing command triggers a background reconnect and the
//! NEXT command awaits a brand-new cycle. A single authz decision makes 2–3 such reads, for
//! a measured 19–28 s; a revoke, 28.4 s.
//!
//! **What the budget actually buys.** Only tolerance while ESTABLISHING a connection.
//! `send_packed_command` never retries a *command* — it surfaces the error to the caller and
//! reconnects in the background. So the case one retry covers is narrow and specific: a
//! first connect attempt landing in a failover gap (old primary gone, new one not yet
//! accepting), which `min_delay` (100–200 ms jittered) is well matched to.
//!
//! **What is deliberately left alone** (SMA-473 D1) — `min_delay`, `exponent_base`,
//! `connection_timeout` (1 s) and `response_timeout` (500 ms). The last two are already
//! bounded by redis-rs and are NOT what costs the time; tightening them was considered and
//! declined. Note the consequence: this bounds a *stopped* Redis (instant `ECONNREFUSED`),
//! not a *blackholed* one, where `connection_timeout` dominates at ~2.1 s per command.

use metrics::{counter, gauge};
use redis::aio::{ConnectionManager, ConnectionManagerConfig};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Retries AFTER the first attempt (redis-rs defaults to 6 — see the module doc for what
/// that costs). One retry covers a first connect attempt landing in a failover gap;
/// anything more just adds latency to a genuine outage.
const CONNECT_RETRIES: usize = 1;

// SPDX-License-Identifier: Apache-2.0
syntax = "proto3";

package paigasus.common.v1;

// The actor behind a change: a principal named by its canonical PRN (ADR-0014).
//
// CONTRACT. Producers MUST write a canonical PRN. Consumers MUST treat an `Actor`
// whose `prn` is empty or unparseable as *unknown* — identically to an absent
// `Actor` — and never as an error. proto3 gives message presence but not field
// presence, so `Actor{prn: ""}` is constructible in every language; this rule is
// what stops that from becoming a second spelling of "unknown".
//
// Deliberately carries no `kind` enum: the PRN's resource-type segment already
// encodes it (user / service-account / principal), and the resource-type accessor is
// exported from the kernel bindings in every language (`prnResourceType` in TS/JS,
// `prn_resource_type` in Rust/Python), so branching on kind does not require a
// duplicated field. It also carries no `display_name`: adding a proto field is
// non-breaking, so it can land the day a consumer needs one.
message Actor {
  // Canonical PRN of the actor, e.g. prn:pgs:iam:::principal/<uuid>.
  string prn = 1;
}
